// =============================
// AI Financial Auditor - Audit Engine V2
// =============================

// Hitung jumlah kemunculan setiap invoice
const invoiceCount = {};

for (const item of items) {
  const inv = (item.json.Invoice_No || "").trim();
  invoiceCount[inv] = (invoiceCount[inv] || 0) + 1;
}

// Audit setiap transaksi
for (const item of items) {

  let score = 0;
  const findings = [];

  const row = item.json;

  // Duplicate Invoice
  if (invoiceCount[row.Invoice_No] > 1) {
    score += 40;
    findings.push("Duplicate Invoice");
  }

  // Large Amount
  if (Number(row.Amount) > 50000000) {
    score += 25;
    findings.push("Large Transaction");
  }

  // Missing Approval
  if (!row.Approved_By || row.Approved_By.trim() === "") {
    score += 20;
    findings.push("Missing Approval");
  }

  // Missing Attachment
  if ((row.Attachment || "").toLowerCase() === "no") {
    score += 15;
    findings.push("Missing Attachment");
  }

  // Duplicate Payment
  if (row.Payment_Status === "Paid Twice") {
    score += 35;
    findings.push("Duplicate Payment");
  }

  // Invalid Date
  if (row.Date === "2026-02-30") {
    score += 20;
    findings.push("Invalid Transaction Date");
  }

  // New Vendor
  if ((row.Vendor || "").startsWith("Vendor Baru")) {
    score += 10;
    findings.push("New Vendor");
  }

  // Risk Level
  let risk = "LOW";

  if (score >= 70) {
    risk = "CRITICAL";
  } else if (score >= 50) {
    risk = "HIGH";
  } else if (score >= 20) {
    risk = "MEDIUM";
  }

  row.Audit_Score = score;
  row.Risk_Level = risk;
  row.Findings = findings.join(", ");
}

return items;

const summary = {
  totalTransactions: items.length,

  riskSummary: {
    LOW: 0,
    MEDIUM: 0,
    HIGH: 0,
    CRITICAL: 0
  },

  issueSummary: {},

  topRiskTransactions: []
};

for (const item of items) {

  const row = item.json;

  // Hitung Risk Level
  if (summary.riskSummary[row.Risk_Level] !== undefined) {
    summary.riskSummary[row.Risk_Level]++;
  }

  // Hitung jenis temuan
  if (row.Findings) {
    if (!summary.issueSummary[row.Findings]) {
      summary.issueSummary[row.Findings] = 0;
    }

    summary.issueSummary[row.Findings]++;
  }

  // Simpan transaksi yang bermasalah
  if ((row.Audit_Score || 0) > 0) {

    summary.topRiskTransactions.push({

      Transaction_ID: row.Transaction_ID,

      Invoice_No: row.Invoice_No,

      Vendor: row.Vendor,

      Amount: row.Amount,

      Audit_Score: row.Audit_Score,

      Risk_Level: row.Risk_Level,

      Findings: row.Findings

    });

  }

}

// Urutkan berdasarkan skor audit tertinggi
summary.topRiskTransactions.sort((a, b) => b.Audit_Score - a.Audit_Score);

// Ambil 20 transaksi paling berisiko
summary.topRiskTransactions =
summary.topRiskTransactions.slice(0, 20);

return [
{
json: summary
}
];

// Mengambil data langsung secara spesifik dari node AI Agent dan Generate Summary
const report = $('AI Agent').first().json.output || "Laporan tidak tersedia.";
const summary = $('Generate Summary').first().json;

const risk = summary.riskSummary;
const issue = summary.issueSummary;

const issueRows = Object.entries(issue)
.map(([name, total]) => `
<tr>
<td>${name}</td>
<td style="text-align:right">${total}</td>
</tr>
`).join("");

const topRows = summary.topRiskTransactions
.map(t => `
<tr>
<td>${t.Transaction_ID}</td>
<td>${t.Invoice_No}</td>
<td>${t.Vendor}</td>
<td style="text-align:right">
Rp ${Number(t.Amount).toLocaleString("id-ID")}
</td>
<td>${t.Risk_Level}</td>
<td>${t.Findings}</td>
</tr>
`)
.join("");

const html = `
