<head>
<meta charset="UTF-8">
<title>Automatic Financial Audit Report</title>
<style>
body{font-family:Arial,sans-serif;background:#f4f7fb;margin:40px;}
.container{background:white;padding:40px;border-radius:8px;box-shadow:0 0 8px rgba(0,0,0,.15);}
.cards{display:flex;gap:15px;margin-bottom:30px;flex-wrap:wrap;}
.card{flex:1;min-width:120px;padding:20px;border-radius:8px;color:white;text-align:center;}
.blue{background:#0d6efd;}
.green{background:#28a745;}
.yellow{background:#ffc107;color:black;}
.red{background:#dc3545;}
.purple{background:#6f42c1;}
table{width:100%;border-collapse:collapse;margin-top:20px;margin-bottom:30px;}
th,td{border:1px solid #ddd;padding:10px;}
th{background:#1f4e79;color:white;}
.report-content{line-height:1.6;color:#333;font-size:14px;white-space:pre-wrap;}
.footer{margin-top:40px;text-align:center;font-size:12px;color:#777;}
</style>
</head>
<body>
<div class="container">
<h1>Automatic Financial Audit Report</h1>
<p><b>Generated:</b> ${new Date().toLocaleString()}</p>

<div class="cards">
<div class="card blue"><h3>Total</h3><h1>${summary.totalTransactions}</h1></div>
<div class="card green"><h3>Low</h3><h1>${risk.LOW}</h1></div>
<div class="card yellow"><h3>Medium</h3><h1>${risk.MEDIUM}</h1></div>
<div class="card red"><h3>High</h3><h1>${risk.HIGH}</h1></div>
<div class="card purple"><h3>Critical</h3><h1>${risk.CRITICAL}</h1></div>
</div>

<h2>Issue Summary</h2>
<table>
<tr><th>Finding</th><th>Total</th></tr>
${issueRows}
</table>

<h2>Executive Report</h2>
<div class="report-content">${report}</div>

<h2>Top Risk Transactions</h2>
<table>
<tr>
<th>ID</th><th>Invoice</th><th>Vendor</th><th>Amount</th><th>Risk</th><th>Findings</th>
</tr>
${topRows}
</table>

